mapper.insert:
INSERT INTO local_client_releases(
    version, platform, architecture, launcher_version_min, launcher_version_max,
    protocol_version, manifest_url, manifest_sha256, manifest_signature,
    compatible, published_at, synced_at
) VALUES (
    #{version}, #{platform}, #{architecture}, #{launcherVersionMin}, #{launcherVersionMax},
    #{protocolVersion}, #{manifestUrl}, #{manifestSha256}, #{manifestSignature},
    #{compatible}, #{publishedAt}, #{syncedAt}
)

INSERT INTO local_client_release_artifacts(
    version, artifact_kind, artifact_url, artifact_size, artifact_sha256, artifact_signature
) VALUES (
    #{version}, #{artifactKind}, #{artifactUrl}, #{artifactSize}, #{artifactSha256}, #{artifactSignature}
)

INSERT INTO local_client_version_policy_audits(
    audit_id, policy_scope, user_id, previous_target_version, target_version,
    revision, action, actor_user_id, created_at
) VALUES (
    #{auditId}, #{scope}, #{userId}, #{previousTargetVersion}, #{targetVersion},
    #{revision}, #{action}, #{actorUserId}, #{createdAt}
)

INSERT INTO local_client_update_rollouts(
    rollout_id, rollout_scope, requested_user_id, status, created_by, created_at, completed_at
) VALUES (
    #{rolloutId}, #{rolloutScope}, #{requestedUserId}, #{status}, #{createdBy}, #{createdAt}, #{completedAt}
)

mapper.select:
SELECT rollout_id, rollout_scope, requested_user_id, status, created_by, created_at, completed_at
FROM local_client_update_rollouts WHERE rollout_id = #{rolloutId}
FOR UPDATE

mapper.update:
UPDATE local_client_update_rollouts
SET status = #{status}, completed_at = #{completedAt}
WHERE rollout_id = #{rolloutId} AND status != #{status}

