INSERT INTO local_client_update_attempts(
    command_id, rollout_id, client_instance_id, user_id, connection_generation,
    policy_revision, current_version, target_version, direction, status,
    release_digest, error_code, created_at, updated_at, completed_at
) VALUES (
    #{commandId}, #{rolloutId}, #{clientInstanceId}, #{userId}, #{connectionGeneration},
    #{policyRevision}, #{currentVersion}, #{targetVersion}, #{direction}, #{status},
    #{releaseDigest}, #{errorCode}, #{createdAt}, #{updatedAt}, #{completedAt}
)
